function normalizeValue(value) {
  return String(value || "").trim().toLowerCase();
}

function toParagraphs(value) {
  return String(value || "")
    .trim()
    .split(/\n\s*\n/g)
    .map((paragraph) => paragraph.replace(/\s+/g, " ").trim())
    .filter(Boolean);
}

